"""Build the local #210 review and compact supplied-clip catalogue."""
from pathlib import Path
import json,csv,html,hashlib
from PIL import Image,ImageDraw
ROOT=Path(__file__).resolve().parents[2];OUT=ROOT/'build/local-blender-kit-v1';REVIEW=OUT/'review'
def main():
    (OUT/'START_HERE.md').write_text((ROOT/'docs/blender-base-contract.md').read_text(encoding='utf-8'),encoding='utf-8')
    sheet=Image.new('RGB',(1260,600),'#171c1c');draw=ImageDraw.Draw(sheet)
    for row,fit in enumerate(['female','male']):
        for col,view in enumerate(['rest-front','rest-side','rest-back','dying-start','dying-middle','dying-end']):
            image=Image.open(REVIEW/(fit+'-'+view+'.png')).resize((210,280),Image.Resampling.LANCZOS)
            sheet.paste(image,(col*210,row*300+20));draw.text((col*210+4,row*300+3),fit+' '+view,fill='#e5ded0')
    sheet.save(REVIEW/'contact-sheet.png')
    manifest=json.loads((OUT/'kit-manifest.json').read_text());clips=json.loads((OUT/'clip-audit.json').read_text())['clips']
    with (OUT/'clip-catalogue.csv').open('w',newline='',encoding='utf-8') as f:
        writer=csv.writer(f);writer.writerow(['file','bones','start_frame','end_frame','fps','action_slot','female_max_rest_angle_deg','male_max_rest_angle_deg','direct_assignment_approved'])
        for c in clips:
            rig=next(o for o in c['objects'] if o['type']=='ARMATURE');a=c['actions'][0]
            writer.writerow([c['file'],len(rig['bones']),*a['frame_range'],c['fps'],a['slots'][0]['identifier'],c['compatibility']['female']['max_local_rest_angle_deg'],c['compatibility']['male']['max_local_rest_angle_deg'],False])
    panels=''
    for fit in ['female','male']:
        record=next(r for r in manifest['fits'] if r['fit_id']==fit+'-v1');body=next(o for o in record['objects'] if o['type']=='MESH');rig=next(o for o in record['objects'] if o['type']=='ARMATURE')
        panels+=f'<article data-fit="{fit}"><h2>{fit.title()} · {record["fit_id"]}</h2><img width="420" height="560" src="{fit}-rest-front.png" alt="Actual Blender {fit} base in neutral front view"><p class="caption">Neutral rest · front</p><p>{body["vertices"]} source vertices · {body["triangles"]} triangles · {len(rig["bones"])} bones</p><p>Source height: {body["bind_bbox"]["dimensions"][2]:.4f} units. Rig, rest transforms and mesh preserved.</p><p><a href="../{fit}_base.blend">Editable Blender master</a> · <a href="../exports/{fit}_base.glb">Verified GLB export</a></p></article>'
    rows=''.join('<tr><td>'+html.escape(c['file'])+'</td><td>'+str(round(c['actions'][0]['frame_range'][1]))+'</td><td>Target-specific retargeting</td></tr>' for c in clips)
    page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Depths · Blender base masters</title><style>body{margin:0;background:#171c1c;color:#e5ded0;font:18px/1.5 system-ui}main{max-width:1100px;margin:auto;padding:24px}h1{font-family:Georgia,serif;font-size:38px}h2{font-size:22px}a{color:#d6b77c}fieldset{border:1px solid #696455;padding:16px;display:flex;gap:16px;flex-wrap:wrap}select{font:inherit;min-height:44px;max-width:100%;background:#27302f;color:inherit;border:1px solid #a19477;padding:5px}.fits{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:22px;margin-top:22px}article{background:#222a29;padding:16px;border:1px solid #68614e;min-width:0}img{display:block;width:100%;height:auto;max-width:420px;margin:auto}p,a,td{overflow-wrap:anywhere}table{width:100%;border-collapse:collapse}td,th{text-align:left;border-bottom:1px solid #4d514a;padding:8px}.notice{border-left:3px solid #c7a86a;padding:12px;background:#252b28}.caption{font-weight:bold}@media(max-width:650px){main{padding:12px}.fits{gap:10px}article{padding:8px}h1{font-size:28px}h2{font-size:18px}}</style><main><h1>Editable base masters</h1><p>#210 · the actual supplied female and male bases, preserved separately in Blender5.2.3. No new face painting, garments or live-game changes.</p><p class="notice">Neutral mode uses the original rest skeleton. Dying previews show three real source-animation samples, reframed to follow the source's root motion. Play the complete Action in Blender. The other34 supplied clips need target-specific retargeting; they are not claimed as fitted/approved motion.</p><fieldset><legend>Inspect both fits</legend><label>Mode <select id="mode"><option value="rest">Neutral rest</option><option value="dying-start">Dying · frame1</option><option value="dying-middle">Dying · frame131</option><option value="dying-end">Dying · frame261</option></select></label><label>Rest angle <select id="angle"><option value="front">Front</option><option value="side">Side</option><option value="back">Back</option></select></label></fieldset><section class="fits">'''+panels+'''</section><h2>Before making clothing</h2><p>The source dimensions differ, and their rest poses differ:65 bones versus49, including16 extra ring/pinky joints on the female. Matching bone names do not make the clips compatible. Direct Idle assignment produced about11° female /52° male upper-limb axis differences. Keep fit IDs separate and retarget before accepting later motion tests.</p><p>The female FBX's missing texture link was restored from the unchanged packed texture in the supplied Blender file. The male remains the supplied plain material. Covered-body groups are empty templates; no body faces have been deleted.</p><h2>Files and checks</h2><p><a href="../START_HERE.md">Beginner guide and fit contract</a> · <a href="../kit-manifest.json">Local source/fit manifest</a> · <a href="../blender-validation.json">Blender reopen/source/export checks</a> · <a href="../transfer-validation.json">Actual clip assignment findings</a> · <a href="../godot-smoke/godot-validation.json">Godot import and motion check</a> · <a href="../clip-catalogue.csv">34-clip catalogue</a></p><h2>Supplied clips</h2><table><thead><tr><th>File</th><th>Last frame</th><th>Use on these fits</th></tr></thead><tbody>'''+rows+'''</tbody></table><p>All source files, masters, textures, exports and actual renders remain in ignored local output. Owner style acceptance and physical iPhone performance remain separate.</p></main><script>function update(){const mode=document.querySelector('#mode').value,angle=document.querySelector('#angle').value;document.querySelector('#angle').disabled=mode!=='rest';for(const panel of document.querySelectorAll('[data-fit]')){const view=mode==='rest'?'rest-'+angle:mode;panel.querySelector('img').src=panel.dataset.fit+'-'+view+'.png';panel.querySelector('img').alt='Actual Blender '+panel.dataset.fit+' '+view;panel.querySelector('.caption').textContent=mode==='rest'?'Neutral rest · '+angle:document.querySelector('#mode').selectedOptions[0].textContent;}}document.querySelector('#mode').addEventListener('change',update);document.querySelector('#angle').addEventListener('change',update);</script></html>'''
    page=page.replace('<h2>Files and checks</h2>','<p><a href="contact-sheet.png">All twelve actual renders</a></p><h2>Files and checks</h2>')
    (REVIEW/'inspector.html').write_text(page,encoding='utf-8')
    print('KIT_REVIEW: local page and34-clip catalogue built')
if __name__=='__main__':main()
